import{_ as r,l as d,o as t,c as i,v as e,p as n,x as o,d as c,i as h,S as l}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"fast-math","description":"","frontmatter":{"title":"fast-math","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fast-math.md","filePath":"cs/fast-math.md","lastUpdated":1789023840000}'),E={name:"cs/fast-math.md"};function f(m,a,p,_,u,b){const s=d("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="fast-math" tabindex="-1">fast-math <a class="header-anchor" href="#fast-math" aria-label="Permalink to &quot;fast-math&quot;">​</a></h1><div class="epigraph"><p>IEEE 754 不承认实数的全部代数：结合律、`0*x`、NaN。fast-math 显式允许编译器按实数代数改写，换速度，丢位模式与异常。</p><footer>—— 据 IEEE 754；Goldberg, What Every Computer Scientist Should Know About Floating-Point Arithmetic；GCC/LLVM `-ffast-math` 文档整理</footer></div><p>上一课<a href="/cs/undefined-behavior-opt">UB 与优化</a>是整数与指针契约。缺口是<strong>浮点</strong>：默认须保持 IEEE（除语言另有规定）。fast-math：允许重结合、忽略 NaN/Inf 的某些路径、把 <code>x+0</code> 当 <code>x</code>（符号零例外被抹掉）。中端课序在此结束：标量/循环优化的合法性两扇门——UB 与浮点旗。下一单元后端分配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>向量化归约、多面体并行求和，都想重结合。IEEE 不许。旗打开则 LICM/CSE 可把 <code>x*2+x*2</code> 变 <code>x*4</code> 一类。缺口是<strong>旗是合同变更</strong>，不是「更聪明的 GVN」。</p><p><code>fma</code> 融合改变舍入，有的旗允许。与<a href="/cs/fp-exceptions">组成课浮点</a> 的异常标志：fast-math 可假定不看状态字。</p><h3 id="fast-math-不是-ub" tabindex="-1">fast-math 不是 UB <a class="header-anchor" href="#fast-math-不是-ub" aria-label="Permalink to &quot;fast-math 不是 UB&quot;">​</a></h3><p>程序仍有定义行为，只是数学上不是 IEEE 的那一个。调试：同一源两种旗结果不同是预期。不要当编译器 bug 开单（除非旗未开却重结合）。</p><p><span class="marginnote">Goldberg 1991。IEEE 754。GCC <code>-ffast-math</code> 拆成 <code>ffinite-math-only</code> 等。本课不把神经网络训练的混合精度当本栏主题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IR 指令带 <code>nnan</code>/<code>ninf</code>/<code>reassoc</code>/<code>contract</code>。变换检查旗。库：<code>sin</code> 可换成近似。报告：优化备注说明因哪一旗启用。</p>',11)),(t(),n(l,null,{default:o(()=>[h(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IEEE%5B%22IEEE%20%E8%BF%90%E7%AE%97%22%5D%20--%3E%20FLAG%5B%22fast-math%20%E6%97%97%22%5D%0A%20%20FLAG%20--%3E%20ALG%5B%22%E5%AE%9E%E6%95%B0%E4%BB%A3%E6%95%B0%E6%94%B9%E5%86%99%22%5D%0A%20%20ALG%20--%3E%20SIMD%5B%22%E5%90%91%E9%87%8F%E5%BD%92%E7%BA%A6%E7%AD%89%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与 PGO：热循环更可能值得开；但旗是编译单元级，不是轮廓自动开。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>符号零、NaN payload、比较的谓词（<code>NaN != NaN</code>）都会被改。数值代码（Kahan 求和）必须关旗。不要全局 <code>CFLAGS=-ffast-math</code> 灌进内核。</p><p>语言：Fortran 传统上更允许重结合；C 默认不允许。对照用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 IEEE 模式。后课默认：无旗则保持浮点语义；有旗才重结合。下一课线性扫描寄存器分配：后端开始，假定 IR 已合法化。</p><p>也不把 fast-math 当定点数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fast-math 显式放弃部分 IEEE，换代数与 SIMD 归约。</li><li>与 UB 不同：仍有定义，只是另一种定义。</li><li>数值稳定代码应关闭。</li><li>出处：IEEE 754；Goldberg, 1991；GCC/LLVM 旗文档。</li></ul>',9))])}const x=r(E,[["render",f]]);export{I as __pageData,x as default};
